{"cards": [{"node_code": "N_d5750306d968b235", "definition": "指管道运输系统中连接首末站及中间站场的长距离输送线路工程，涵盖路由勘察、选线设计、管沟开挖、管道敷设及线路附属设施。", "boundary": "本节点聚焦于“线”的连续输送部分，即站与站之间的管道本体及其沿线工程。边界在于区分“干线”与“站场”：站场内的工艺管道、设备基础及站内道路归入站场工程；干线工程侧重野外长距离敷设、地形适应性及线路保护。若涉及管道材料力学性能，归入管道结构与设计；若涉及具体焊接工艺，归入管道施工与机械。", "includes": ["管道路由勘察、选线原则及地形地质适应性分析", "管沟开挖、管道下沟、回填及线路标识工程", "穿越河流、公路、铁路等障碍物的工程措施"], "excludes": ["首末站、分输站、压气站等站场内部的工艺管道与设备布置（归入站场工程）", "管道管体、管件的材料选择与结构强度计算（归入管道结构与设计）"], "sibling_distinctions": [{"other_code": "N_53dc3cd8ad9fd359", "rule": "干线工程关注站与站之间的长距离输送线路；站场工程关注首末站、分输站等节点内部的工艺设施与土建。"}, {"other_code": "N_da81833e12314275", "rule": "干线工程包含线路主体；辅助建筑物与设备指沿线分散设置的阀室、阴极保护站等非站场类小型设施。"}], "cross_boundary_rule": "涉及穿越工程时，若为长距离干线穿越，归入本节点；若为站场内部短距离穿越，归入站场工程。"}, {"node_code": "N_53dc3cd8ad9fd359", "definition": "指管道运输系统中首末站、分输站、压气站、清管站等节点工程，涵盖站内工艺管道、设备基础、土建建筑及公用工程。", "boundary": "本节点聚焦于“点”的节点设施，即流体进行加压、分输、计量、清管等作业的集中区域。边界在于区分“站场”与“干线”：站场工程侧重站内工艺布局、设备基础及建筑物；干线工程侧重站间长距离管道敷设。若涉及站内具体泵、阀、压缩机的选型与结构，归入管道结构与设计；若涉及站内通信与自控系统，归入相应专项节点。", "includes": ["首末站、分输站、压气站等站场工艺设计与总图布置", "站内工艺管道、设备基础、管廊及土建建筑工程", "站场公用工程（供电、给排水、消防、暖通等）"], "excludes": ["站与站之间的长距离输送管道工程（归入干线工程）", "站内具体工艺设备（如泵、阀、压缩机）的结构设计与选型（归入管道结构与设计）"], "sibling_distinctions": [{"other_code": "N_d5750306d968b235", "rule": "站场工程关注节点内部的工艺设施与土建；干线工程关注节点之间的长距离输送线路。"}, {"other_code": "N_da81833e12314275", "rule": "站场工程是集中式的大型节点设施；辅助建筑物与设备是沿线分散设置的小型阀室、保护站等。"}], "cross_boundary_rule": "涉及站内设备布置时，若侧重总图、基础及工艺管道连接，归入本节点；若侧重设备本体参数，归入管道结构与设计。"}, {"node_code": "N_da81833e12314275", "definition": "指管道沿线分散设置的、非站场类的辅助性建筑物与设备，如阀室、阴极保护站、水工保护设施、线路标识及小型附属设施。", "boundary": "本节点聚焦于“线”上分散的辅助设施，服务于干线安全运行与维护。边界在于区分“辅助建筑物”与“站场”：站场是集中处理流体的大型节点；辅助建筑物是沿线小型、分散的设施，如手动/电动阀室、阴极保护测试桩、河流/公路穿越保护结构等。若涉及大型压气站或分输站，归入站场工程；若涉及通信光缆或自控系统，归入相应专项节点。", "includes": ["沿线阀室（手动/电动）、阴极保护站、测试桩等小型建筑物", "河流、公路、铁路等穿越工程的水工保护与加固设施", "线路标识、里程桩、警示牌及小型附属设施"], "excludes": ["首末站、分输站、压气站等集中式大型节点工程（归入站场工程）", "长距离输送管道本体及管沟工程（归入干线工程）"], "sibling_distinctions": [{"other_code": "N_d5750306d968b235", "rule": "辅助建筑物与设备是干线上的点状附属设施；干线工程是连续的管道敷设主体。"}, {"other_code": "N_53dc3cd8ad9fd359", "rule": "辅助建筑物与设备是小型、分散的沿线设施；站场工程是大型、集中的节点设施。"}], "cross_boundary_rule": "涉及穿越保护时，若为干线长距离穿越，归入本节点；若为站场内部短距离穿越，归入站场工程。"}]}
